<template>
  <div class="demo-page">
    <header>
      <p class="demo-page__eyebrow">远程组件</p>
      <h1 class="demo-page__title">comps-vue3 · HelloWorld</h1>
      <p class="demo-page__lead">
        下面的组件由 <code>preFetchLib('comps-vue3')</code> 从远端加载，宿主产物里没有它。
        右侧属性面板来自 <code>libs-vue3-leva</code>，<code>msg</code> / <code>name</code>
        改动会实时写回远程组件。
      </p>
    </header>

    <DemoPreview class="remote-preview">
      <LevaPlayground
        name="HelloWorld"
        :component="RemoteComp"
        :schema="HelloWorldSchema"
        :presets="{ msg: '来自 demo-vue3 的问候' }"
      />
    </DemoPreview>

    <p class="demo-note">
      远程组件的 <code>HelloWorld</code> 声明了 <code>props: { msg, name }</code>，面板通过
      <code>v-bind</code> 把值传给组件；schema 由 <code>vue3-leva-gen-schema</code> 从组件源码的
      props 注释生成，宿主只负责把组件和 schema 传进 <code>PropsPlayground</code>。
    </p>

    <p class="demo-note">
      远端地址：开发 <code>http://localhost:20020</code>（先执行
      <code>pnpm comps-vue3:dev</code>），生产 <code>unpkg</code> 上的
      <code>hel-meta.json</code>；也可用 <code>VITE_REMOTE_HOST</code> 覆盖。
    </p>
  </div>
</template>

<script setup lang="ts">
import { defineAsyncComponent } from 'vue'
import HelloWorldSchema from '@melt-js/comps-vue3/src/components/HelloWorld.propsSchema.json'
import DemoPreview from '../components/DemoPreview.vue'
import LevaPlayground from '../components/LevaPlayground.vue'
import { loadRemoteLib } from '../configs/remote'

const RemoteComp = defineAsyncComponent({
  loader: async () => {
    console.log('[demo-vue3] 开始加载远程组件...')

    try {
      // 入口处已经预加载，这里复用同一个 Promise（通常已 resolve）
      const lib = await loadRemoteLib()

      console.log('[demo-vue3] 远程组件加载完成:', lib)
      return lib.HelloWorld
    } catch (err) {
      console.error('[demo-vue3] 获取远程组件失败:', err)
      throw err
    }
  },
  timeout: 10000,
})
</script>

<style scoped>
/* 全屏时只保留远程组件与面板，页头与说明文字留在屏幕外 */
.remote-preview.is-demo-fullscreen {
  padding: 16px;
  background: var(--demo-bg);
}
</style>
